import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { WalletEntity } from './entities/wallet.entity';
import { LedgerEntryEntity } from './entities/ledger-entry.entity';

/**
 * Result of reconciling a single wallet against its ledger.
 * All money fields are expressed in minor units (cents).
 */
export interface WalletReconciliationResult {
  walletId: string;
  expectedBalance: number;
  actualBalance: number;
  drift: number;
  compensatingAmount: number;
}

@Injectable()
export class WalletReconciliationService {
  constructor(
    @InjectRepository(WalletEntity)
    private readonly walletRepository: Repository<WalletEntity>,
    @InjectRepository(LedgerEntryEntity)
    private readonly ledgerRepository: Repository<LedgerEntryEntity>,
  ) {}

  /**
   * Recomputes the wallet's expected balance from its ledger entries,
   * compares it against the persisted actual balance, and derives the
   * compensating amount that would bring the wallet back into balance.
   * The result is returned as a plain object that gets serialized straight
   * to JSON for downstream consumers (saga orchestrator, audit service, etc).
   */
  async reconcile(walletId: string): Promise<WalletReconciliationResult> {
    const wallet = await this.walletRepository.findOneByOrFail({
      id: walletId,
    });

    const entries = await this.ledgerRepository.find({
      where: { walletId },
    });

    // Sum every ledger entry (minor units, e.g. cents) into the expected balance.
    const expectedBalance: number = entries.reduce(
      (sum, entry) => sum + entry.amountMinorUnits,
      0,
    );

    // The balance currently persisted on the wallet row, also in minor units.
    const actualBalance: number = wallet.balanceMinorUnits;

    // Ordinary JS subtraction: both operands are plain numbers (IEEE-754 doubles).
    const drift = expectedBalance - actualBalance;

    // The amount that must be posted as a compensating transaction to bring
    // actualBalance back in line with expectedBalance.
    const compensatingAmount = -drift;

    return {
      walletId,
      expectedBalance,
      actualBalance,
      drift,
      compensatingAmount,
    };
  }
}
